pub(crate) fn evidence_bundle_archive_raw_ref(archive_id: &str, archive_hash: &str) -> String {
    format!("endpoint-evidence-bundle-archive:{archive_id}:{archive_hash}")
}

fn first_graph_attribute(graph: &CausalGraph, key: &str) -> Option<String> {
    graph
        .nodes
        .values()
        .find_map(|node| node_attribute_string(&node.attributes, key))
}

pub(crate) fn node_attribute_string(
    attributes: &std::collections::BTreeMap<String, serde_json::Value>,
    key: &str,
) -> Option<String> {
    attributes
        .get(key)
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToString::to_string)
}

pub(crate) fn non_empty(value: Option<&str>) -> Option<&str> {
    value.map(str::trim).filter(|value| !value.is_empty())
}

fn graph_context_has_attribute(context: &CausalGraph, key: &str, expected: &str) -> bool {
    context
        .nodes
        .values()
        .any(|node| node_attribute_string(&node.attributes, key).as_deref() == Some(expected))
        || context
            .edges
            .iter()
            .any(|edge| node_attribute_string(&edge.attributes, key).as_deref() == Some(expected))
}

fn graph_agent_context(context: &CausalGraph) -> (Vec<String>, Vec<String>) {
    let mut node_ids = BTreeSet::new();
    let mut labels = BTreeSet::new();
    for node in context.nodes.values() {
        if node.kind == CausalNodeKind::Tool {
            node_ids.insert(node.node_id.clone());
            labels.insert(node.label.clone());
            continue;
        }
        if node.kind == CausalNodeKind::Process {
            if let Some(agent_id) = node_attribute_string(&node.attributes, "agentId") {
                node_ids.insert(node.node_id.clone());
                labels.insert(agent_id);
            }
        }
    }
    (node_ids.into_iter().collect(), labels.into_iter().collect())
}

fn resolve_graph_root(
    root_node_id: Option<&str>,
    process: Option<&EndpointProcess>,
) -> Result<String, (StatusCode, String)> {
    if let Some(root_node_id) = root_node_id
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        return Ok(root_node_id.to_string());
    }

    if let Some(process) = process {
        return Ok(process.stable_node_id());
    }

    Err((
        StatusCode::BAD_REQUEST,
        "root_node_id or process must be provided".to_string(),
    ))
}

fn graph_root_process_selector(input: &EdrGraphRootProcessSelectorInput) -> EndpointProcess {
    EndpointProcess {
        pid: input.pid,
        ppid: input.ppid,
        process_guid: trimmed_owned(input.process_guid.as_deref()),
        parent_process_guid: trimmed_owned(input.parent_process_guid.as_deref()),
        image: trimmed_owned(input.image.as_deref()),
        command_line: trimmed_owned(input.command_line.as_deref()),
        cwd: trimmed_owned(input.cwd.as_deref()),
        ..EndpointProcess::default()
    }
}

pub(crate) fn resolve_graph_root_from_selector(
    root_node_id: Option<&str>,
    process: Option<&EdrGraphRootProcessSelectorInput>,
) -> Result<String, (StatusCode, String)> {
    let process = process.map(graph_root_process_selector);
    resolve_graph_root(root_node_id, process.as_ref())
}

pub(crate) fn bounded_graph_depth(field: &str, depth: Option<usize>) -> Result<usize, (StatusCode, String)> {
    let depth = depth.unwrap_or(EDR_MAX_CAUSAL_SUBGRAPH_DEPTH);
    if depth <= EDR_MAX_CAUSAL_SUBGRAPH_DEPTH {
        return Ok(depth);
    }
    Err((
        StatusCode::BAD_REQUEST,
        format!("{field} must be at most {EDR_MAX_CAUSAL_SUBGRAPH_DEPTH}"),
    ))
}

pub(crate) fn bounded_request_limit(
    field: &str,
    limit: Option<usize>,
    default: usize,
    max: usize,
) -> Result<usize, (StatusCode, String)> {
    let limit = limit.unwrap_or(default);
    if (1..=max).contains(&limit) {
        return Ok(limit);
    }
    Err((
        StatusCode::BAD_REQUEST,
        format!("{field} must be between 1 and {max}"),
    ))
}

pub(crate) fn bounded_provider_timeout_ms(
    field: &str,
    timeout_ms: Option<u64>,
) -> Result<u64, (StatusCode, String)> {
    let timeout_ms = timeout_ms.unwrap_or(EDR_DEFAULT_PROVIDER_ACK_TIMEOUT_MS);
    if (1..=EDR_MAX_PROVIDER_ACK_TIMEOUT_MS).contains(&timeout_ms) {
        return Ok(timeout_ms);
    }
    Err((
        StatusCode::BAD_REQUEST,
        format!("{field} must be between 1 and {EDR_MAX_PROVIDER_ACK_TIMEOUT_MS}"),
    ))
}

fn bounded_u32_setting(
    field: &str,
    value: u32,
    min: u32,
    max: u32,
) -> Result<u32, (StatusCode, String)> {
    if (min..=max).contains(&value) {
        return Ok(value);
    }
    Err((
        StatusCode::BAD_REQUEST,
        format!("{field} must be between {min} and {max}"),
    ))
}

fn bounded_u16_setting(
    field: &str,
    value: u16,
    min: u16,
    max: u16,
) -> Result<u16, (StatusCode, String)> {
    if (min..=max).contains(&value) {
        return Ok(value);
    }
    Err((
        StatusCode::BAD_REQUEST,
        format!("{field} must be between {min} and {max}"),
    ))
}

fn normalize_settings_url(
    field: &str,
    value: &str,
    allow_non_loopback_http: bool,
) -> Result<String, (StatusCode, String)> {
    let trimmed = value.trim().trim_end_matches('/');
    if trimmed.is_empty() {
        return Err((
            StatusCode::BAD_REQUEST,
            format!("{field} must not be empty"),
        ));
    }
    let parsed = reqwest::Url::parse(trimmed).map_err(|err| {
        (
            StatusCode::BAD_REQUEST,
            format!("{field} must be a valid URL: {err}"),
        )
    })?;
    if parsed.host_str().is_none() {
        return Err((
            StatusCode::BAD_REQUEST,
            format!("{field} must include a host"),
        ));
    }
    if !parsed.username().is_empty() || parsed.password().is_some() {
        return Err((
            StatusCode::BAD_REQUEST,
            format!("{field} must not contain userinfo"),
        ));
    }
    match parsed.scheme() {
        "https" => {}
        "http" if allow_non_loopback_http || control_api_url_is_loopback(&parsed) => {}
        "http" => {
            return Err((
                StatusCode::BAD_REQUEST,
                format!("{field} may use http only for loopback hosts"),
            ));
        }
        other => {
            return Err((
                StatusCode::BAD_REQUEST,
                format!("{field} must use http or https, got {other}"),
            ));
        }
    }
    Ok(trimmed.to_string())
}

fn normalize_notification_severity_setting(value: &str) -> Result<String, (StatusCode, String)> {
    match value.trim().to_ascii_lowercase().as_str() {
        "info" | "allow" | "allowed" => Ok("info".to_string()),
        "warn" | "warning" | "medium" => Ok("warn".to_string()),
        "block" | "blocked" | "high" | "critical" => Ok("block".to_string()),
        _ => Err((
            StatusCode::BAD_REQUEST,
            "notification_severity must be one of info, warn, or block".to_string(),
        )),
    }
}

fn normalize_ota_mode_setting(value: &str) -> Result<String, (StatusCode, String)> {
    match value.trim().to_ascii_lowercase().as_str() {
        "auto" => Ok("auto".to_string()),
        "manual" => Ok("manual".to_string()),
        _ => Err((
            StatusCode::BAD_REQUEST,
            "ota_mode must be one of auto or manual".to_string(),
        )),
    }
}

fn normalize_ota_channel_setting(value: &str) -> Result<String, (StatusCode, String)> {
    match value.trim().to_ascii_lowercase().as_str() {
        "stable" => Ok("stable".to_string()),
        "beta" => Ok("beta".to_string()),
        _ => Err((
            StatusCode::BAD_REQUEST,
            "ota_channel must be one of stable or beta".to_string(),
        )),
    }
}

pub(crate) async fn build_edr_detection_candidate(
    state: &AgentApiState,
    input: EdrDetectionCandidateInput,
) -> Result<EdrDetectionCandidateResponse, (StatusCode, String)> {
    let root_node_id =
        resolve_graph_root_from_selector(input.root_node_id.as_deref(), input.process.as_ref())?;
    let max_depth = bounded_graph_depth("maxDepth", input.max_depth)?;
    let graph = state.edr_flight_recorder.lock().await.graph().clone();
    let subgraph = edr_policy_simulation_graph_slice(&graph, root_node_id.as_str(), max_depth)
        .ok_or_else(|| {
            (
                StatusCode::NOT_FOUND,
                format!("detection candidate target not found in causal graph: {root_node_id}"),
            )
        })?;
    let root_node = subgraph.nodes.get(&root_node_id).ok_or_else(|| {
        (
            StatusCode::NOT_FOUND,
            format!("detection candidate root not found in graph slice: {root_node_id}"),
        )
    })?;
    let action = input
        .action
        .unwrap_or_else(|| default_detection_candidate_action(root_node));
    if !supported_edr_simulation_action(&action) {
        return Err((
            StatusCode::BAD_REQUEST,
            format!(
                "unsupported endpoint detection candidate action: {}",
                action.as_str()
            ),
        ));
    }
    let rule_id = detection_candidate_rule_id(root_node, &action);
    let description = input
        .description
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToString::to_string)
        .unwrap_or_else(|| detection_candidate_description(root_node, &action));
    let rule = EndpointPolicySimulationRule {
        rule_id: rule_id.clone(),
        action: action.clone(),
        description: Some(description.clone()),
    };
    let simulation = EndpointPolicySimulationReport::for_rule(rule, &root_node_id, &subgraph);
    let receipt = emit_edr_simulation_receipt(state, &simulation, &subgraph)
        .await
        .map_err(internal_error)?;
    let recommended_stage = recommended_detection_stage(&simulation);
    let stage_plan = detection_candidate_stage_plan(&simulation, &recommended_stage);
    let candidate = EdrDetectionCandidate {
        rule_id,
        action,
        description,
        root_node_id: root_node_id.clone(),
        root_label: root_node.label.clone(),
        root_kind: root_node.kind.clone(),
        graph_slice_id: simulation.graph_slice_id.clone(),
    };

    Ok(EdrDetectionCandidateResponse {
        candidate,
        recommended_stage,
        stage_plan,
        simulation,
        graph: subgraph,
        receipt,
    })
}

pub(crate) fn policy_replay_rule_id(
    policy: &EndpointPolicySnapshot,
    node: &CausalNode,
    action: &EndpointDecisionAction,
) -> String {
    format!(
        "endpoint.current_policy_replay.epoch_{}.{}.{}.{}",
        policy.policy_epoch,
        action.as_str(),
        causal_node_kind_name(&node.kind),
        rule_id_fragment(&node.label)
    )
}

pub(crate) fn policy_replay_description(
    policy: &EndpointPolicySnapshot,
    node: &CausalNode,
    action: &EndpointDecisionAction,
) -> String {
    format!(
        "Replay current endpoint policy {} epoch {} against captured {} node {} with simulated {} enforcement.",
        policy.policy_version,
        policy.policy_epoch,
        causal_node_kind_name(&node.kind),
        node.label,
        action.as_str()
    )
}

pub(crate) fn edr_policy_simulation_graph_slice(
    graph: &CausalGraph,
    root_node_id: &str,
    max_depth: usize,
) -> Option<CausalGraph> {
    graph
        .causal_context_around(root_node_id, max_depth, max_depth)
        .or_else(|| graph.causal_subgraph_from(root_node_id, max_depth))
}

pub(crate) fn build_policy_replay_report(
    policy: EndpointPolicySnapshot,
    root_node: &CausalNode,
    flight_recorder_observation_count: usize,
    simulation: &EndpointPolicySimulationReport,
    graph: &CausalGraph,
) -> EdrPolicyReplayReport {
    let policy_epoch = policy.policy_epoch.to_string();
    let replay_id = local_stable_id(
        "policy_replay",
        [
            policy.policy_hash.as_str(),
            policy_epoch.as_str(),
            simulation.simulation_id.as_str(),
        ],
    );
    let observation_count = graph
        .edges
        .iter()
        .filter_map(|edge| {
            let observation_id = edge.observation_id.trim();
            (!observation_id.is_empty()).then_some(observation_id)
        })
        .collect::<BTreeSet<_>>()
        .len();
    let summary = format!(
        "Replayed graph slice {} under current endpoint policy {} epoch {}; {} would affect {} nodes and {} edges with developer breakage score {}/100.",
        simulation.graph_slice_id,
        policy.policy_version,
        policy.policy_epoch,
        simulation.rule_id,
        simulation.affected_node_count,
        simulation.affected_edge_count,
        simulation.developer_breakage_score
    );

    EdrPolicyReplayReport {
        replay_id,
        replayed_at: chrono::Utc::now(),
        mode: "current_policy_graph_replay".to_string(),
        policy,
        root_node_id: simulation.root_node_id.clone(),
        root_label: root_node.label.clone(),
        root_kind: root_node.kind.clone(),
        action: simulation.action.clone(),
        graph_slice_id: simulation.graph_slice_id.clone(),
        observation_count,
        node_count: graph.nodes.len(),
        edge_count: graph.edges.len(),
        flight_recorder_observation_count,
        would_enforce: simulation.would_block,
        developer_breakage_score: simulation.developer_breakage_score,
        impact_level: simulation.impact_level.clone(),
        summary,
    }
}

pub(crate) fn normalize_staged_detection_hash(
    field: &str,
    value: Option<String>,
) -> Result<Option<String>, (StatusCode, String)> {
    let Some(value) = value else {
        return Ok(None);
    };
    let value = value.trim();
    if value.is_empty() {
        return Ok(None);
    }
    if value.len() != 66 || !value.starts_with("0x") {
        return Err((
            StatusCode::BAD_REQUEST,
            format!("{field} must be a 0x-prefixed SHA-256 hex digest"),
        ));
    }
    if !value[2..].chars().all(|ch| ch.is_ascii_hexdigit()) {
        return Err((
            StatusCode::BAD_REQUEST,
            format!("{field} must be a 0x-prefixed SHA-256 hex digest"),
        ));
    }
    Ok(Some(value.to_ascii_lowercase()))
}

pub(crate) struct PolicyDeltaApplyEnforcementProofInput<'a> {
    pub(crate) settings: &'a Settings,
    pub(crate) local_policy: EndpointPolicySnapshot,
    pub(crate) cross_window_impact_hash: Option<&'a str>,
    pub(crate) cross_window_recommendation_hash: Option<&'a str>,
    pub(crate) daemon_policy_reload_requested: bool,
    pub(crate) daemon_restart_requested: bool,
    pub(crate) provider_ack_timeout_ms: u64,
}

pub(crate) async fn build_policy_delta_apply_enforcement_proof(
    state: &Arc<AgentApiState>,
    input: PolicyDeltaApplyEnforcementProofInput<'_>,
) -> Result<EdrPolicyDeltaApplyEnforcementProof> {
    let PolicyDeltaApplyEnforcementProofInput {
        settings,
        local_policy,
        cross_window_impact_hash,
        cross_window_recommendation_hash,
        daemon_policy_reload_requested,
        daemon_restart_requested,
        provider_ack_timeout_ms,
    } = input;
    let mut daemon_restarted = false;
    let mut daemon_restart_error = None;
    if daemon_restart_requested {
        match state.daemon_manager.restart().await {
            Ok(()) => {
                daemon_restarted = true;
            }
            Err(err) => {
                daemon_restart_error = Some(err.to_string());
            }
        }
    }

    let daemon_policy_reload =
        request_daemon_policy_reload(state.as_ref(), settings, daemon_policy_reload_requested)
            .await;
    let network_extension_policy_reload = request_policy_delta_network_extension_reload(
        state.as_ref(),
        settings,
        provider_ack_timeout_ms,
    )
    .await;
    let daemon = state.daemon_manager.status().await;
    let daemon_policy_version = tokio::time::timeout(
        POLICY_VERSION_FETCH_TIMEOUT,
        fetch_daemon_policy_version(state.as_ref()),
    )
    .await
    .ok()
    .flatten();
    let provider_status_refresh =
        refresh_macos_provider_status(state, provider_ack_timeout_ms).await;
    let (macos_host, provider_policy_acknowledgements, provider_acknowledgement_poll) =
        wait_for_provider_policy_acknowledgements(state, &local_policy, provider_ack_timeout_ms)
            .await;
    let sensor_state = endpoint_sensor_state_from_macos_host(&macos_host);
    let receipt_evidence =
        policy_delta_apply_enforcement_receipt_evidence(PolicyDeltaApplyEnforcementEvidenceInput {
            local_policy: &local_policy,
            daemon_policy_reload: &daemon_policy_reload,
            network_extension_policy_reload: &network_extension_policy_reload,
            provider_status_refresh: &provider_status_refresh,
            provider_acknowledgement_poll: &provider_acknowledgement_poll,
            provider_policy_acknowledgements: &provider_policy_acknowledgements,
            daemon_restart_requested,
            daemon_restarted,
            daemon_restart_error: daemon_restart_error.as_deref(),
            daemon_policy_version: daemon_policy_version.as_deref(),
            cross_window_impact_hash,
            cross_window_recommendation_hash,
        });
    let receipt = emit_edr_sensor_state_receipt_with_evidence(
        state.as_ref(),
        local_policy.clone(),
        sensor_state.clone(),
        "post policy delta apply protection state",
        &receipt_evidence,
    )
    .await?;
    let degraded_provider_receipts = emit_edr_provider_degradation_receipts(
        state.as_ref(),
        local_policy.clone(),
        sensor_state.clone(),
    )
    .await?;

    Ok(EdrPolicyDeltaApplyEnforcementProof {
        policy_synced_to_disk: true,
        cross_window_impact_hash: cross_window_impact_hash.map(str::to_string),
        cross_window_recommendation_hash: cross_window_recommendation_hash.map(str::to_string),
        local_policy,
        daemon_policy_reload,
        network_extension_policy_reload,
        provider_status_refresh,
        provider_acknowledgement_poll,
        provider_policy_acknowledgements,
        daemon_restart_requested,
        daemon_restarted,
        daemon_restart_error,
        daemon,
        daemon_policy_version,
        sensor_state,
        receipt,
        degraded_provider_receipts,
    })
}

pub(crate) async fn refresh_macos_provider_status(
    state: &Arc<AgentApiState>,
    timeout_ms: u64,
) -> EdrProviderStatusRefreshResult {
    if timeout_ms == 0 {
        return EdrProviderStatusRefreshResult {
            requested: false,
            refreshed: false,
            timeout_ms,
            elapsed_ms: 0,
            error: None,
        };
    }

    let started = Instant::now();
    match state
        .macos_host
        .request_refresh(Duration::from_millis(timeout_ms))
        .await
    {
        Ok(_) => EdrProviderStatusRefreshResult {
            requested: true,
            refreshed: true,
            timeout_ms,
            elapsed_ms: started.elapsed().as_millis().min(u128::from(u64::MAX)) as u64,
            error: None,
        },
        Err(err) => EdrProviderStatusRefreshResult {
            requested: true,
            refreshed: false,
            timeout_ms,
            elapsed_ms: started.elapsed().as_millis().min(u128::from(u64::MAX)) as u64,
            error: Some(err.to_string()),
        },
    }
}

fn provider_policy_acknowledgements_for_policy(
    status: &CombinedSystemExtensionStatus,
    policy: &EndpointPolicySnapshot,
) -> Vec<EdrProviderPolicyAcknowledgement> {
    vec![
        provider_policy_acknowledgement(
            "macos.endpoint_security",
            EndpointProviderKind::EndpointSecurity,
            &status.endpoint_security,
            policy,
            false,
            false,
        ),
        provider_policy_acknowledgement(
            "macos.network_extension",
            EndpointProviderKind::NetworkExtension,
            &status.network_extension,
            policy,
            true,
            true,
        ),
    ]
}

async fn wait_for_provider_policy_acknowledgements(
    state: &Arc<AgentApiState>,
    policy: &EndpointPolicySnapshot,
    timeout_ms: u64,
) -> (
    CombinedSystemExtensionStatus,
    Vec<EdrProviderPolicyAcknowledgement>,
    EdrProviderAcknowledgementPoll,
) {
    let started = Instant::now();
    let timeout = Duration::from_millis(timeout_ms);
    let mut attempts = 0u64;

    loop {
        attempts = attempts.saturating_add(1);
        let status = state.macos_host.snapshot().await;
        let acknowledgements = provider_policy_acknowledgements_for_policy(&status, policy);
        let satisfied = acknowledgements.iter().all(|ack| ack.acknowledged);
        let elapsed = started.elapsed();

        if satisfied || timeout_ms == 0 || elapsed >= timeout {
            return (
                status,
                acknowledgements,
                EdrProviderAcknowledgementPoll {
                    requested: timeout_ms > 0,
                    timeout_ms,
                    elapsed_ms: elapsed.as_millis().min(u128::from(u64::MAX)) as u64,
                    attempts,
                    satisfied,
                },
            );
        }

        let remaining = timeout.saturating_sub(elapsed);
        tokio::time::sleep(remaining.min(EDR_PROVIDER_ACK_POLL_INTERVAL)).await;
    }
}

fn provider_policy_acknowledgement(
    provider_id: &str,
    provider_kind: EndpointProviderKind,
    provider: &ProviderStatus,
    policy: &EndpointPolicySnapshot,
    require_policy_synced: bool,
    require_enforcement_ready: bool,
) -> EdrProviderPolicyAcknowledgement {
    let active = provider_policy_ack_active(provider);
    let policy_epoch_matches = provider
        .policy_epoch
        .map(|observed| observed == policy.policy_epoch);
    let mut reasons = Vec::new();

    if !active {
        reasons.push("provider_not_active".to_string());
    }
    match &provider.runtime {
        ProviderRuntimeState::Degraded { reason } => {
            if reason.trim().is_empty() {
                reasons.push("provider_degraded".to_string());
            } else {
                reasons.push(format!(
                    "provider_degraded:{}",
                    sanitize_provider_status_reason(reason)
                ));
            }
        }
        ProviderRuntimeState::Unknown => reasons.push("provider_runtime_unknown".to_string()),
        ProviderRuntimeState::Inactive => reasons.push("provider_runtime_inactive".to_string()),
        ProviderRuntimeState::Active => {}
    }
    match policy_epoch_matches {
        Some(true) => {}
        Some(false) => reasons.push("policy_epoch_mismatch".to_string()),
        None => reasons.push("policy_epoch_unreported".to_string()),
    }
    if provider.policy_synced == Some(false) {
        reasons.push("policy_not_synced".to_string());
    } else if require_policy_synced && provider.policy_synced != Some(true) {
        reasons.push("policy_sync_unreported".to_string());
    }
    if provider.enforcement_ready == Some(false) {
        reasons.push("enforcement_not_ready".to_string());
    } else if require_enforcement_ready && provider.enforcement_ready != Some(true) {
        reasons.push("enforcement_readiness_unreported".to_string());
    }
    if let Some(last_error) = provider
        .last_error
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        reasons.push(format!(
            "provider_last_error:{}",
            sanitize_provider_status_reason(last_error)
        ));
    }
    append_provider_attestation_not_ready_reasons(provider, &mut reasons);

    reasons.sort();
    reasons.dedup();

    EdrProviderPolicyAcknowledgement {
        provider_id: provider_id.to_string(),
        provider_kind,
        active,
        observed_policy_epoch: provider.policy_epoch,
        expected_policy_epoch: policy.policy_epoch,
        policy_epoch_matches,
        policy_synced: provider.policy_synced,
        enforcement_ready: provider.enforcement_ready,
        acknowledged: reasons.is_empty(),
        reasons,
    }
}

fn provider_policy_ack_active(provider: &ProviderStatus) -> bool {
    matches!(provider.runtime, ProviderRuntimeState::Active)
        || provider
            .provider_state
            .as_ref()
            .map(|state| state.active)
            .unwrap_or(false)
}

fn append_provider_attestation_not_ready_reasons(
    provider: &ProviderStatus,
    reasons: &mut Vec<String>,
) {
    let Some(provider_state) = provider.provider_state.as_ref() else {
        return;
    };
    if !provider_state.active {
        reasons.push("provider_state_inactive".to_string());
    }
    if !provider_state.healthy {
        reasons.push("provider_state_unhealthy".to_string());
    }
    match provider_state.availability {
        ProviderAvailability::Unavailable => {
            reasons.push("provider_state_unavailable".to_string());
        }
        ProviderAvailability::Inactive => reasons.push("provider_state_inactive".to_string()),
        ProviderAvailability::Active => {}
        ProviderAvailability::Degraded => reasons.push("provider_state_degraded".to_string()),
    }
    reasons.extend(
        provider_state
            .degraded_reasons
            .iter()
            .map(|reason| reason.trim())
            .filter(|reason| !reason.is_empty())
            .map(|reason| {
                format!(
                    "provider_state_degraded:{}",
                    sanitize_provider_status_reason(reason)
                )
            }),
    );
}

fn network_extension_response_not_ready_reasons(provider: &ProviderStatus) -> Vec<String> {
    let mut reasons = Vec::new();

    if !provider_policy_ack_active(provider) {
        reasons.push("provider_not_active".to_string());
    }
    match &provider.runtime {
        ProviderRuntimeState::Degraded { reason } => {
            if reason.trim().is_empty() {
                reasons.push("provider_degraded".to_string());
            } else {
                reasons.push(format!(
                    "provider_degraded:{}",
                    sanitize_provider_status_reason(reason)
                ));
            }
        }
        ProviderRuntimeState::Unknown => reasons.push("provider_runtime_unknown".to_string()),
        ProviderRuntimeState::Inactive => reasons.push("provider_runtime_inactive".to_string()),
        ProviderRuntimeState::Active => {}
    }
    if provider.policy_synced == Some(false) {
        reasons.push("policy_not_synced".to_string());
    } else if provider.policy_synced != Some(true) {
        reasons.push("policy_sync_unreported".to_string());
    }
    if provider.enforcement_ready == Some(false) {
        reasons.push("enforcement_not_ready".to_string());
    } else if provider.enforcement_ready != Some(true) {
        reasons.push("enforcement_readiness_unreported".to_string());
    }
    if let Some(last_error) = provider
        .last_error
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        reasons.push(format!(
            "provider_last_error:{}",
            sanitize_provider_status_reason(last_error)
        ));
    }
    append_provider_attestation_not_ready_reasons(provider, &mut reasons);

    reasons.sort();
    reasons.dedup();
    reasons
}

pub(crate) fn network_extension_egress_policy_proof_enforcement_ready(
    snapshot_decodable: bool,
    provider: &ProviderStatus,
) -> bool {
    snapshot_decodable && network_extension_response_not_ready_reasons(provider).is_empty()
}

async fn ensure_network_extension_ready_for_restrict_egress(
    state: &AgentApiState,
) -> Result<(), (StatusCode, String)> {
    let status = state.macos_host.snapshot().await;
    let reasons = network_extension_response_not_ready_reasons(&status.network_extension);
    if reasons.is_empty() {
        return Ok(());
    }
    Err((
        StatusCode::CONFLICT,
        format!(
            "network extension provider is not ready for restrict_egress: {}",
            reasons.join(", ")
        ),
    ))
}

pub(crate) struct PolicyDeltaApplyEnforcementEvidenceInput<'a> {
    local_policy: &'a EndpointPolicySnapshot,
    daemon_policy_reload: &'a EdrDaemonPolicyReloadResult,
    network_extension_policy_reload: &'a NetworkExtensionReloadRequestProof,
    provider_status_refresh: &'a EdrProviderStatusRefreshResult,
    provider_acknowledgement_poll: &'a EdrProviderAcknowledgementPoll,
    provider_policy_acknowledgements: &'a [EdrProviderPolicyAcknowledgement],
    daemon_restart_requested: bool,
    daemon_restarted: bool,
    daemon_restart_error: Option<&'a str>,
    daemon_policy_version: Option<&'a str>,
    cross_window_impact_hash: Option<&'a str>,
    cross_window_recommendation_hash: Option<&'a str>,
}

